examples.template:
Column {
    Box(
        modifier = Modifier.onPreviewKeyEvent { event ->
            val shortcut = event.type == KeyEventType.KeyDown && event.isCtrlPressed && event.key == Key.K
            if (shortcut) open = true
            shortcut
        },
    ) {
        MonarchButton(text = {{trigger}}, onClick = { open = true })
    }
    MonarchText(text = last?.let { "Ran: " + it } ?: {{hint}})
}
if (open) {
    MonarchBottomSheet(
        onDismissRequest = {
            open = false
            query = ""
        },
    ) {
        Column(modifier = Modifier.fillMaxHeight()) {
            MonarchSearchBar(
                query = query,
                onQueryChange = { query = it },
                onSearch = {},
                modifier = Modifier.fillMaxWidth(),
                placeholder = "Type a command or search",
            )
            MonarchSearchResults(
                groups = matches,
                onSelect = { result, _ ->
                    last = result.title
                    open = false
                    query = ""
                },
                modifier = Modifier.weight(1f),
                query = query,
            )
        }
    }
}

examples.setupTemplate:
var open by rememberSaveable { mutableStateOf(true) }
var query by rememberSaveable { mutableStateOf("") }
var last by rememberSaveable { mutableStateOf<String?>(null) }
val commands = listOf(
    MonarchSearchResultGroup(
        title = {{groups.0.title}},
        id = {{groups.0.id}},
        results = listOf(
            MonarchSearchResult(title = {{groups.0.items.0.label}}, id = {{groups.0.items.0.id}}, meta = "C", icon = { MonarchIcon(SampleIcons.Plus, contentDescription = null) }),
            MonarchSearchResult(title = {{groups.0.items.1.label}}, id = {{groups.0.items.1.id}}, meta = "F2", icon = { MonarchIcon(SampleIcons.Pencil, contentDescription = null) }),
            MonarchSearchResult(title = {{groups.0.items.2.label}}, id = {{groups.0.items.2.id}}, icon = { MonarchIcon(SampleIcons.Trash, contentDescription = null) }),
            // {{groups.0.items.2.tone}}: the row is a danger action on the web; native rows have no tone.
        ),
    ),
    MonarchSearchResultGroup(
        title = {{groups.1.title}},
        id = {{groups.1.id}},
        results = listOf(
            MonarchSearchResult(title = {{groups.1.items.0.label}}, id = {{groups.1.items.0.id}}, meta = "G B", icon = { MonarchIcon(SampleIcons.Board, contentDescription = null) }),
            MonarchSearchResult(title = {{groups.1.items.1.label}}, id = {{groups.1.items.1.id}}, meta = "G M", icon = { MonarchIcon(SampleIcons.List, contentDescription = null) }),
            MonarchSearchResult(title = {{groups.1.items.2.label}}, id = {{groups.1.items.2.id}}, snippet = {{groups.1.items.2.description}}, meta = "Ctrl ,"),
        ),
    ),
)
val matches = commands.map { group ->
    MonarchSearchResultGroup(
        title = group.title,
        id = group.id,
        results = group.results.filter { it.title.contains(query.trim(), ignoreCase = true) },
    )
}

